  const languages={Русский:{en:'Russian',zh:'俄语',de:'Russisch',es:'ruso',it:'russo'},English:{en:'English',zh:'英语',de:'Englisch',es:'inglés',it:'inglese'},中文:{en:'Chinese',zh:'中文',de:'Chinesisch',es:'chino',it:'cinese'},Deutsch:{en:'German',zh:'德语',de:'Deutsch',es:'alemán',it:'tedesco'},Español:{en:'Spanish',zh:'西班牙语',de:'Spanisch',es:'español',it:'spagnolo'},Italiano:{en:'Italian',zh:'意大利语',de:'Italienisch',es:'italiano',it:'italiano'}};
  const exact=translations[value];if(exact)return exact[locale]||value;
