async function loadAdminSettings(){
  const root=$('#adminContent');
  try{
    const payload=await api('/api/admin/settings');
    const raw=payload&&typeof payload==='object'?payload:{};
    const callbacks=raw.callbacks&&typeof raw.callbacks==='object'?raw.callbacks:{};
    const oauthHtml=['yandex','github','mailru'].map(provider=>{
      const id=typeof raw['oauth.'+provider+'.client_id']==='string'?raw['oauth.'+provider+'.client_id']:'';
      const secret=raw['oauth.'+provider+'.client_secret'];
      const secretConfigured=Boolean(secret&&typeof secret==='object'&&secret.configured);
      const ready=Boolean(id&&(provider==='mailru'||secretConfigured));
      const callback=callbacks[provider]||'https://demoground.ru/api/oauth/'+provider+'/callback';
      const secretLabel=provider==='mailru'?'Client Secret · для VK ID не требуется':'Client Secret';
      const secretPlaceholder=secretConfigured?'Секрет сохранён · оставьте пустым':'Секрет приложения';
      return `<fieldset class="oauth-setting"><legend>${providerIcon(provider)} ${providerName(provider)}</legend><span class="oauth-status ${ready?'is-ready':''}">${ready?'Настроено':'Нужны ключи приложения'}</span><label>Адрес перенаправления<code>${esc(callback)}</code></label><label>Client ID<input class="text-field" name="oauth.${provider}.client_id" autocomplete="off" placeholder="ID приложения" value="${esc(id)}"></label><label>${secretLabel}<input class="text-field" name="oauth.${provider}.client_secret" type="password" autocomplete="new-password" placeholder="${secretPlaceholder}"></label></fieldset>`;
    }).join('');
    const proxyValue=typeof raw['youtube.proxy_url']==='string'?raw['youtube.proxy_url']:'';
    root.innerHTML=`<form id="adminSettingsForm" class="admin-settings-form"><h3>Вход через соцсети</h3><p class="field-note">Укажите Client ID и секрет приложения там, где он требуется. Адрес перенаправления скопируйте в настройки каждого приложения.</p>${oauthHtml}<h3>Прокси для YouTube (Cloudflare / SOCKS5 / HTTP)</h3><p class="field-note">Укажите адрес вашего Cloudflare или внешнего прокси для загрузки видео с YouTube. Если поле пустое, используется системное подключение.</p><div class="proxy-settings-box"><div class="proxy-input-row"><input class="text-field" name="youtube.proxy_url" id="youtubeProxyInput" placeholder="http://... или socks5://..." value="${esc(proxyValue)}"><button type="button" class="outline-button" id="testProxyBtn">⚡ Проверить прокси</button></div><div id="proxyTestResult" class="proxy-test-result"></div></div><div id="settingsMessage" class="field-note"></div><button type="submit" class="primary-button">Сохранить настройки</button></form>`;
    $('#testProxyBtn').onclick=async()=>{
      const btn=$('#testProxyBtn'),res=$('#proxyTestResult');btn.disabled=true;res.className='proxy-test-result checking';res.textContent='⏳ Проверяем доступ к YouTube через прокси…';
      try{const response=await api('/api/admin/proxy/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({proxy_url:$('#youtubeProxyInput').value.trim()})});res.className='proxy-test-result '+(response.ok?'success':'error');res.textContent=(response.ok?'🟢 ':'🔴 ')+response.message}
      catch(err){res.className='proxy-test-result error';res.textContent='🔴 Ошибка: '+err.message}
      finally{btn.disabled=false}
    };
    $('#adminSettingsForm').onsubmit=async event=>{
      event.preventDefault();const values={};
      for(const el of event.currentTarget.elements){if(el.name)values[el.name]=el.type==='checkbox'?el.checked:el.value}
      try{await api('/api/admin/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values})});$('#settingsMessage').textContent='Настройки сохранены'}
      catch(err){$('#settingsMessage').textContent=err.message}
    };
  }catch(err){root.textContent=err.message}
}
