function drawLectures(){const ready=lectures.filter(l=>l.status==='ready').length;$('#lectureCount').textContent=lectures.length;$('#readyCount').textContent=ready;const visible=currentFolderId?lectures.filter(l=>l.folder_id===currentFolderId):lectures;$('#emptyState').classList.toggle('hidden',visible.length>0);$('#lectureList').hidden=libraryView==='bookmarks'||!visible.length;const list=$('#lectureList'),existing=new Map([...list.children].map(c=>[c.dataset.id,c]));for(const [i,l] of visible.entries()){let card=existing.get(l.id);if(!card){card=document.createElement('article');card.className='lecture-card';card.dataset.id=l.id;card.innerHTML='<div class="lecture-card-top"><div class="lecture-icon">▷</div><div class="lecture-card-actions"><span class="lecture-status"></span><div class="card-dots-wrap"><button class="card-dots-btn" type="button" aria-label="Меню лекции" title="Действия"><svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><circle cx="5" cy="12" r="1.75"/><circle cx="12" cy="12" r="1.75"/><circle cx="19" cy="12" r="1.75"/></svg></button><div class="card-menu-dropdown hidden"><button type="button" class="card-menu-item move-action"><svg class="menu-item-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path></svg><span>Переместить в папку</span></button><button type="button" class="card-menu-item delete-action"><svg class="menu-item-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg><span>Удалить лекцию</span></button></div></div></div></div><h3></h3><div class="lecture-card-detail"></div>';card.onclick=()=>openLecture(card.dataset.id);const dotsBtn=card.querySelector('.card-dots-btn');const dropdown=card.querySelector('.card-menu-dropdown');const moveBtn=card.querySelector('.card-menu-item.move-action');const deleteBtn=card.querySelector('.card-menu-item.delete-action');dropdown.onclick=e=>e.stopPropagation();dotsBtn.onclick=e=>{e.stopPropagation();const willOpen=dropdown.classList.contains('hidden');$$('.card-menu-dropdown').forEach(d=>d.classList.add('hidden'));$$('.card-dots-wrap').forEach(w=>w.classList.remove('open'));if(willOpen){dropdown.classList.remove('hidden');card.querySelector('.card-dots-wrap').classList.add('open')}};moveBtn.onclick=e=>{e.stopPropagation();dropdown.classList.add('hidden');card.querySelector('.card-dots-wrap').classList.remove('open');openMoveModal(card.dataset.id)};deleteBtn.onclick=async e=>{e.stopPropagation();dropdown.classList.add('hidden');card.querySelector('.card-dots-wrap').classList.remove('open');const lec=lectures.find(item=>item.id===card.dataset.id);if(!lec||!confirm(`Удалить лекцию «${lec.title}»?`))return;try{await api(`/api/lectures/${lec.id}`,{method:'DELETE'});lectures=lectures.filter(item=>item.id!==lec.id);drawLectures();await loadFolders()}catch(err){alert(err.message)}};}existing.delete(l.id);card.style.setProperty('--card-index',Math.min(i,8));card.querySelector('h3').textContent=l.title;const icon=card.querySelector('.lecture-icon');if(icon)icon.innerHTML=l.thumbnail_url?`<img src="${esc(l.thumbnail_url)}" alt="" loading="lazy">`:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 9 6-9 6z"/></svg>';const badge=card.querySelector('.lecture-status');badge.textContent=statusText(l);badge.className=`lecture-status ${l.status==='ready'?'':l.status}`;const detail=card.querySelector('.lecture-card-detail');const state=l.status==='ready'?'ready':l.status==='error'?'error':l.status==='cancelled'?'cancelled':'working';if(card.dataset.state!==state){card.dataset.state=state;detail.innerHTML=state==='ready'?`<p>${stamp(l.duration)} · ${l.outline?.length||0} ${chapterCountLabel(l.outline?.length||0)}</p>`:state==='error'?'<p>Нажмите, чтобы увидеть ошибку</p>':state==='cancelled'?'<p>Обработка отменена</p>':progressMarkup(l)}if(state==='ready'){const count=detail.querySelector('p');if(count)count.textContent=`${stamp(l.duration)} · ${l.outline?.length||0} ${chapterCountLabel(l.outline?.length||0)}`}else if(state==='working'){const pct=Math.max(0,Math.min(100,Number(l.progress)||0)),progress=detail.querySelector('[role=progressbar]');if(progress){const head=progress.previousElementSibling,foot=progress.nextElementSibling;head.querySelector('span').textContent=localizeProcessingStage(l.status==='queued'?'Подготовка к обработке':l.stage||'Обработка');head.querySelector('b').textContent=`${pct}%`;progress.classList.toggle('indeterminate',l.status==='queued'||pct===0);progress.setAttribute('aria-valuenow',pct);progress.querySelector('i').style.width=`${pct}%`;foot.textContent=etaText(l)}}if(list.children[i]!==card)list.insertBefore(card,list.children[i]||null)}for(const card of existing.values())card.remove();$('#readyCount').title=`${ready} готовы`;if(libraryPollTimer)clearTimeout(libraryPollTimer);libraryPollTimer=lectures.some(l=>['queued','processing'].includes(l.status))?setTimeout(loadLectures,2500):null}
async function loadLectures(){if(libraryLoading)return libraryLoading;libraryLoading=api('/api/lectures').then(rows=>{lectures=rows.map(l=>observeEta(l,true));drawLectures();updateAssistantScope();return rows}).catch(e=>{console.warn(e);return lectures}).finally(()=>{libraryLoading=null});return libraryLoading}
