async function loadBookmarks(){try{bookmarks=await api('/api/bookmarks');$('#bookmarkCount').textContent=bookmarks.length;$('#bookmarkEmpty').classList.toggle('hidden',bookmarks.length>0);$('#bookmarkList').innerHTML=bookmarks.map(item=>`<article class="bookmark-card" data-bookmark="${esc(item.id)}"><button class="bookmark-open" data-id="${esc(item.lecture_id)}" data-time="${Number(item.position)||0}">${item.thumbnail_url?`<img src="${esc(item.thumbnail_url)}" alt="" loading="lazy">`:''}<span><b>${esc(item.title)}</b><small>${stamp(item.position)}</small></span></button><textarea maxlength="1000" aria-label="Заметка к закладке">${esc(item.note||'')}</textarea><div><button class="bookmark-save" type="button">Сохранить заметку</button><button class="bookmark-delete" type="button">Удалить</button></div></article>`).join('');$('#bookmarkList').onclick=async e=>{const card=e.target.closest('[data-bookmark]');if(!card)return;const item=bookmarks.find(x=>x.id===card.dataset.bookmark);if(e.target.closest('.bookmark-open')){const b=e.target.closest('.bookmark-open');openLecture(b.dataset.id,Number(b.dataset.time)||0)}else if(e.target.closest('.bookmark-save')){await api(`/api/bookmarks/${item.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:card.querySelector('textarea').value})});await loadBookmarks()}else if(e.target.closest('.bookmark-delete')){await api(`/api/bookmarks/${item.id}`,{method:'DELETE'});await loadBookmarks()}}}catch(error){console.warn('Bookmarks unavailable',error)}}
