function openMoveModal(lectureId){movingLectureId=lectureId;const lecture=lectures.find(l=>l.id===lectureId);if(!lecture)return;$('#moveLectureModalTitle').textContent='Переместить лекцию';$('#moveLectureModalLead').textContent=`«${lecture.title}»`;$('#moveNewFolderName').value='';$('#moveFolderError').textContent='';const list=$('#moveFolderList');let html=`<button type="button" class="move-folder-item ${!lecture.folder_id?'active':''}" data-folder-id=""><span class="move-folder-icon">▤</span><span class="move-folder-name">Без папки (основная библиотека)</span>${!lecture.folder_id?'<span class="move-current-badge">текущая</span>':''}</button>`;folders.forEach(f=>{const isCurrent=lecture.folder_id===f.id;html+=`<button type="button" class="move-folder-item ${isCurrent?'active':''}" data-folder-id="${esc(f.id)}"><span class="move-folder-icon">▱</span><span class="move-folder-name">${esc(f.name)}</span><span class="move-folder-count">${f.lecture_count||0}</span>${isCurrent?'<span class="move-current-badge">текущая</span>':''}</button>`});list.innerHTML=html;list.querySelectorAll('.move-folder-item').forEach(btn=>{btn.onclick=async()=>{const targetFolderId=btn.dataset.folderId||null;try{await api(`/api/lectures/${movingLectureId}/folder`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder_id:targetFolderId})});const l=lectures.find(item=>item.id===movingLectureId);if(l)l.folder_id=targetFolderId;closeModal($('#moveLectureModal'));await Promise.all([loadFolders(),loadLectures()])}catch(err){$('#moveFolderError').textContent=err.message}}});$('#moveLectureModal').classList.remove('hidden')}
