let searchSequence=0;
function highlightSearchText(text,query){const stops=new Set(['который','которая','которые','потому','поэтому','например','сейчас','вообще','значит','можно','будет','здесь','также','когда','чтобы','просто','этого','этот','это','они','она','есть','быть','как','что','или','для','при','над','под']);const terms=[...query.toLocaleLowerCase('ru-RU').matchAll(/[\p{L}\p{N}]{3,}/gu)].map(m=>m[0]).filter(t=>!stops.has(t));const tokens=[...String(text).matchAll(/[\p{L}\p{N}]+/gu)];let result='',cursor=0;for(const token of tokens){result+=esc(String(text).slice(cursor,token.index));const word=token[0],normalized=word.toLocaleLowerCase('ru-RU'),matched=terms.some(term=>normalized===term||(normalized.length>=4&&term.length>=4&&(normalized.startsWith(term.slice(0,4))||term.startsWith(normalized.slice(0,4)))));result+=matched?`<mark class="search-hit">${esc(word)}</mark>`:esc(word);cursor=token.index+word.length}return result+esc(String(text).slice(cursor))}
function search(){const q=$('#searchInput').value.trim(),sequence=++searchSequence;if(q.length<2){$('#searchResults').innerHTML='';$('#searchHint').textContent='Ищет по всем готовым лекциям';return}$('#searchHint').textContent='Ищем совпадения по смыслу и словам…';api(`/api/search?q=${encodeURIComponent(q)}&language=${encodeURIComponent(window.getUiLanguage?.()||'ru')}`).then(rows=>{if(sequence!==searchSequence)return;$('#searchHint').textContent=rows.length?`${rows.length} подходящих фрагментов`:'Совпадений пока нет';$('#searchResults').innerHTML=rows.map(r=>`<article class="result-card" data-id="${esc(r.lecture_id)}" data-time="${r.start}"><div class="result-time">${stamp(r.start).slice(3)}</div><div class="result-copy"><b>${esc(r.title)} <span style="color:#81916d;font-weight:500">· ${Math.round(r.score*100)}%</span></b><p>${highlightSearchText(r.text,q)}</p></div></article>`).join('');$$('.result-card').forEach(c=>c.onclick=()=>openLecture(c.dataset.id,Number(c.dataset.time)))}).catch(e=>{if(sequence===searchSequence)$('#searchHint').textContent=e.message})}
$('#searchButton').onclick=search;$('#searchInput').onkeydown=e=>{if(e.key==='Enter')search()};$('#searchInput').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(search,450)};$('#navBookmarks').onclick=()=>{currentFolderId=null;showLibraryView('bookmarks')};$('#navAll').onclick=()=>{showLibraryView('all');currentFolderId=null;try{localStorage.removeItem('lectoriumFolder')}catch{}drawFolders();drawLectures();window.scrollTo({top:0,behavior:'smooth'})};
