function syncTranscript(t){const transcriptTab=$('.detail-tabs button[data-panel="transcript"].active');if(!transcriptTab)return;let found=displayTranscriptRows.findIndex(row=>t>=row.start&&t<row.end);if(found<0&&displayTranscriptRows.length&&t>=displayTranscriptRows.at(-1).end)found=displayTranscriptRows.length-1;const list=$('#transcriptList');if(found<0||!list)return;if(found!==lastActiveTranscriptRow){$$('.transcript-line').forEach(row=>row.classList.toggle('active',Number(row.dataset.rowIndex)===found));lastActiveTranscriptRow=found;const active=$(`.transcript-line[data-row-index="${found}"]`);if(active&&Date.now()>=transcriptManualScrollUntil){const target=Math.max(0,active.offsetTop-list.offsetTop-(list.clientHeight-active.offsetHeight)/2);list.scrollTo({top:target,behavior:'smooth'})}}}
async function handleAuthLinks(){const q=new URLSearchParams(location.search),error=q.get('oauth_error'),linked=q.get('linked');if(error){const messages={not_linked:'Сначала привяжите эту соцсеть к аккаунту по паролю.',already_linked:'Эта соцсеть уже связана с другим аккаунтом.',state_expired:'Время входа истекло. Попробуйте ещё раз.',provider_failed:'Не удалось войти через соцсеть. Проверьте настройки OAuth.'};$('#authError').textContent=messages[error]||'Не удалось завершить вход';showAuth();history.replaceState(null,'',location.pathname)}if(linked){$('#accountButton').click();history.replaceState(null,'',location.pathname)}}
