let assistantHistory=[],assistantVersion=0,assistantController=null;
const assistantLocale=()=>assistantCopy[window.getUiLanguage?.()||'ru']||assistantCopy.ru;
function resetAssistant(){assistantVersion++;assistantController?.abort();assistantController=null;assistantHistory=[];$('#assistantMessages').replaceChildren();$('#assistantSend').disabled=false;$('#assistantInput').disabled=false;}
function updateAssistantScope(){
 const select=$('#assistantScope'),previous=select.value,c=assistantLocale();
 const choices=[['all',c[4]],...folders.map(f=>['folder:'+f.id,'▱ '+f.name]),...lectures.filter(l=>l.status==='ready').map(l=>['lecture:'+l.id,'▷ '+l.title])];
 select.innerHTML=choices.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('');
 if(choices.some(([v])=>v===previous))select.value=previous;
 else if(previous!=='all')resetAssistant();
}
function translateAssistant(){const c=assistantLocale();['assistantEyebrow','assistantTitle','assistantDescription','assistantScopeLabel'].forEach((id,i)=>$('#'+id).textContent=c[i]);$('#assistantClear').textContent=c[5];$('#assistantInput').placeholder=c[6];$('#assistantInput').setAttribute('aria-label',c[6]);$('#assistantSend').textContent=c[7];$('#assistantNote').textContent=c[8];updateAssistantScope();}
$('#assistantScope').onfocus=updateAssistantScope;
$('#assistantScope').onpointerdown=updateAssistantScope;
$('#assistantScope').onchange=resetAssistant;
$('#assistantClear').onclick=()=>{resetAssistant();$('#assistantInput').value='';$('#assistantInput').focus()};
$('#assistantForm').onsubmit=async event=>{
 event.preventDefault();const question=$('#assistantInput').value.trim();if(question.length<2||$('#assistantSend').disabled)return;
 const version=assistantVersion,scope=$('#assistantScope').value,c=assistantLocale();
 const questionNode=document.createElement('p');questionNode.className='assistant-question';questionNode.textContent=question;$('#assistantMessages').append(questionNode);
 const response=document.createElement('article');response.className='assistant-answer';response.textContent=c[9];$('#assistantMessages').append(response);
 $('#assistantInput').value='';$('#assistantSend').disabled=true;$('#assistantInput').disabled=true;
 assistantController=new AbortController();
 try{
  const payload={question,language:window.getUiLanguage?.()||'ru',history:assistantHistory};
  if(scope.startsWith('lecture:'))payload.lecture_id=scope.slice(8);
  if(scope.startsWith('folder:'))payload.folder_id=scope.slice(7);
  const result=await api('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:assistantController.signal});
  if(version!==assistantVersion)return;
  response.innerHTML=`<strong>${esc(result.mode==='extracts'?c[10]:c[11])}</strong><p class="assistant-answer-text">${esc(result.answer)}</p>`;
  if(result.sources.length){const list=document.createElement('div');list.className='assistant-sources';list.setAttribute('aria-label',c[12]);result.sources.forEach((source,i)=>{const button=document.createElement('button');button.type='button';button.textContent=`[${i+1}] ${source.title} · ${stamp(source.start)}${source.kind==='summary'?' · ≡':''}`;button.onclick=()=>openLecture(source.lecture_id,source.start);list.append(button)});response.append(list)}
  assistantHistory.push({question,answer:result.answer});assistantHistory=assistantHistory.slice(-4);
 }catch(error){if(version===assistantVersion&&error.name!=='AbortError')response.textContent=error.message;}
 finally{if(version===assistantVersion){$('#assistantSend').disabled=false;$('#assistantInput').disabled=false;$('#assistantInput').focus();assistantController=null;}}
};
